              "type": "contact_p",
              "variable": "TurnUp",
              "id": "r1_0",
              "row": 0,
              "col": 0
            },
            "hasWire": true
          },
          {
            "element": {
              "type": "function",
              "functionName": "ADD",
              "operands": ["Ups", "512"],
              "output": "Ups",
              "id": "r1_1",
              "row": 0,
              "col": 1
            },
            "hasWire": true
          },
